import java.util.Scanner;

public class CF_723B {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();

        String regexPattern = "\\([a-zA-Z_]*\\)";
        String replacedString = s.replaceAll(regexPattern, "_");

        String[] partsArray = replacedString.split("_+");
        int maxLengthFound = 0;
        for (String part : partsArray) {
            if (part.length() > maxLengthFound) {
                maxLengthFound = part.length();
            }
        }
        System.out.println(maxLengthFound);

        int totalCount = 0;
        boolean inParen = false;
        int startIdx = -1, endIdx = -1;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                inParen = true;
                startIdx = i;
            } else if (ch == ')' && inParen) {
                inParen = false;
                endIdx = i;
                String insideStr = s.substring(startIdx + 1, endIdx);
                if (!insideStr.isEmpty()) {
                    String[] segmentsInside = insideStr.split("_+");
                    totalCount += segmentsInside.length - (insideStr.startsWith("_") ? 1 : 0);
                }
            }
        }
        System.out.println(totalCount);
    }
}
